-- Activate Test 17 only AFTER independent media/CDN verification.
-- Existing students, clocks and prior paper versions are untouched.
begin;
insert into academy_tcf_listening.papers(id,version,content)
values('tcf-listening-17','tcf-listening-2026-11-test17-v1',$paper17${"id":"tcf-listening-17","version":"tcf-listening-2026-11-test17-v1","title":"TCF Listening · Test 17","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La scène représente une personne assise, occupée à consulter un devis de fournisseur.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle consulte un devis de fournisseur à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle consulte un devis de fournisseur à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.164,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Un homme présente une affiche liée à économie et entreprises.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur économie et entreprises à un groupe.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur économie et entreprises à un groupe."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.504,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Deux interlocuteurs préparent une rencontre des petits entrepreneurs autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une rencontre des petits entrepreneurs autour d'une table. D. Deux personnes traversent une rivière.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une rencontre des petits entrepreneurs autour d'une table. D. Deux personnes traversent une rivière."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.627,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'illustration montre une personne portant un sac devant la chambre de commerce d'Amiens.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Des enfants jouent dans un jardin. B. Une femme porte un sac devant la chambre de commerce d'Amiens. C. Une femme nage dans une piscine. D. Un homme répare un vélo.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Des enfants jouent dans un jardin. B. Une femme porte un sac devant la chambre de commerce d'Amiens. C. Une femme nage dans une piscine. D. Un homme répare un vélo."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":17.63,"slotSeconds":33},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de gestion de trésorerie ?\nA. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de gestion de trésorerie ?"},{"voice":"female","text":"A. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie."}],"audio":"q-05.mp3","audioSeconds":19.261,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un devis de fournisseur pour participer à une rencontre des petits entrepreneurs ?\nA. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un devis de fournisseur pour participer à une rencontre des petits entrepreneurs ?"},{"voice":"female","text":"A. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place."}],"audio":"q-06.mp3","audioSeconds":20.196,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de gestion de trésorerie ?\nA. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de gestion de trésorerie ?"},{"voice":"female","text":"A. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles."}],"audio":"q-07.mp3","audioSeconds":17.334,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une rencontre des petits entrepreneurs. Est-ce possible ?\nA. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une rencontre des petits entrepreneurs. Est-ce possible ?"},{"voice":"female","text":"A. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage."}],"audio":"q-08.mp3","audioSeconds":21.867,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["un accompagnement gratuit à la transition numérique","la suppression de toutes les activités","une hausse générale des tarifs","la fermeture définitive du lieu"],"correct":"A","explanation":"L'annonce présente précisément un accompagnement gratuit à la transition numérique sans annoncer de fermeture ni d'augmentation.","transcript":"Question 9.\nInformation aux visiteurs. Dans la chambre de commerce d'Amiens, à compter de lundi prochain, nous mettons en place un accompagnement gratuit à la transition numérique. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la chambre de commerce d'Amiens, à compter de lundi prochain, nous mettons en place un accompagnement gratuit à la transition numérique. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.728,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le bâtiment vient d'être vendu.","Les deux personnes ont décidé d'annuler l'activité.","L'inscription exige un paiement supplémentaire.","L'une des personnes ne peut pas arriver à l'heure initiale."],"correct":"D","explanation":"Le rendez-vous est décalé parce qu'une réunion empêche une arrivée à l'heure.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de gestion de trésorerie ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de gestion de trésorerie ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.384,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["En envoyant un courrier postal au responsable.","En téléphonant uniquement le dimanche matin.","En remplissant un formulaire sur le site avant jeudi.","En payant directement sur place le jour même."],"correct":"C","explanation":"L'inscription se fait en ligne avant jeudi et donne lieu à une confirmation.","transcript":"Question 11.\nUne rencontre autour de économie et entreprises aura lieu dans la chambre de commerce d'Amiens. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre autour de économie et entreprises aura lieu dans la chambre de commerce d'Amiens. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":23.713,"slotSeconds":39},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Attendre une réponse par la poste.","Montrer sa confirmation à l'accueil.","Quitter définitivement l'événement.","Reprendre toute la procédure de paiement."],"correct":"B","explanation":"Le responsable demande le message de confirmation pour retrouver le dossier.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de gestion de trésorerie, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de gestion de trésorerie, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.908,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["Le début de la séance est reporté d'une heure.","L'activité change de ville.","La séance est supprimée pour toute la saison.","Tous les participants doivent s'inscrire à nouveau."],"correct":"A","explanation":"L'annonce ne modifie que l'heure de début, de quatorze à quinze heures.","transcript":"Question 13.\nMessage aux participants de un atelier de gestion de trésorerie. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants de un atelier de gestion de trésorerie. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.285,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Annuler définitivement l'activité sans prévenir.","Remplacer les participants par une autre équipe.","Déplacer la rencontre dans une autre région.","Maintenir la présentation et envoyer la démonstration plus tard."],"correct":"D","explanation":"Ils maintiennent une partie de l'activité et prévoient un complément ultérieur.","transcript":"Question 14.\nLe matériel destiné à un atelier de gestion de trésorerie n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de gestion de trésorerie n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.055,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Toutes les difficultés ont été résolues immédiatement.","Les habitants n'ont pas été informés du changement.","Un nouveau dispositif répond à un besoin, mais ses limites restent à évaluer.","Le service est fermé définitivement depuis plusieurs années."],"correct":"C","explanation":"Le reportage expose l'objectif du dispositif, une contrainte persistante et un bilan à venir.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la chambre de commerce d'Amiens : un accompagnement gratuit à la transition numérique. Le dispositif vise à répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges. Plusieurs représentants soulignent toutefois que les délais de livraison sont parfois difficiles à anticiper. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la chambre de commerce d'Amiens : un accompagnement gratuit à la transition numérique. Le dispositif vise à répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges. Plusieurs représentants soulignent toutefois que les délais de livraison sont parfois difficiles à anticiper. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.028,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Pour modifier le prix des inscriptions.","Pour garantir une présence à l'accueil toute la journée.","Pour supprimer toutes les permanences de l'après-midi.","Parce qu'un événement a été déplacé à l'étranger."],"correct":"B","explanation":"Les collègues se relaient afin que personne ne trouve l'accueil fermé.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le mentorat des commerces indépendants.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le mentorat des commerces indépendants."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.062,"slotSeconds":42},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Aux personnes qui éprouvent des difficultés d'accès au service habituel.","Uniquement aux salariés de l'équipe d'accueil.","Aux visiteurs ayant déjà terminé toutes les démarches.","Exclusivement aux responsables politiques."],"correct":"A","explanation":"Le message vise les usagers dont l'accès au service habituel est difficile.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la chambre de commerce d'Amiens. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les petites entreprises manquent de marge pour absorber les hausses de charges. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la chambre de commerce d'Amiens. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les petites entreprises manquent de marge pour absorber les hausses de charges. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.761,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["L'établissement a perdu son paiement.","Elle a décidé d'abandonner l'événement.","Le responsable a refusé toutes les réservations.","Elle ne sera pas disponible à l'heure initialement proposée."],"correct":"D","explanation":"La personne travaille vendredi et choisit un horaire compatible.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une rencontre des petits entrepreneurs. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une rencontre des petits entrepreneurs. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.798,"slotSeconds":47},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Parce que toutes les salles ont été fermées.","Pour demander davantage de frais aux visiteurs.","Pour favoriser les échanges et les questions.","Parce que la visite est réservée aux professionnels."],"correct":"C","explanation":"La limite vise à faciliter l'interaction avec l'animateur.","transcript":"Question 19.\nÀ l'occasion de une rencontre des petits entrepreneurs, des visites en petits groupes seront proposées dans la chambre de commerce d'Amiens. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"À l'occasion de une rencontre des petits entrepreneurs, des visites en petits groupes seront proposées dans la chambre de commerce d'Amiens. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":25.327,"slotSeconds":42},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle veut reporter une réservation de transport.","Elle souhaite obtenir des garanties sur la prévisibilité des coûts et l'accès au financement.","Elle trouve le prix trop élevé.","Elle ne connaît pas le lieu de rendez-vous."],"correct":"B","explanation":"Elle juge les horaires adaptés mais souhaite éclaircir la question de la prévisibilité des coûts et l'accès au financement.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la prévisibilité des coûts et l'accès au financement. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la prévisibilité des coûts et l'accès au financement. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.484,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Pour répartir les équipes selon les besoins des différents créneaux.","Pour sélectionner uniquement les personnes ayant déjà travaillé dans le secteur.","Pour annuler les activités prévues après midi.","Pour demander le paiement anticipé d’une inscription."],"correct":"A","explanation":"Les organisateurs veulent équilibrer les effectifs tout au long de la journée.","transcript":"Question 21.\nAnnonce locale. Dans la chambre de commerce d'Amiens, à l’occasion de une rencontre des petits entrepreneurs, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la chambre de commerce d'Amiens, à l’occasion de une rencontre des petits entrepreneurs, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":37.03,"slotSeconds":54},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Le gain financier assuré dès la première séance.","La disparition complète des difficultés d’organisation.","L’obligation de poursuivre l’activité chaque semaine.","Les échanges durables et les liens de confiance entre les participants."],"correct":"D","explanation":"L’invitée insiste sur les liens humains et les idées partagées plutôt que sur un bénéfice immédiat.","transcript":"Question 22.\nVous participez à un atelier de gestion de trésorerie. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les petites entreprises manquent de marge pour absorber les hausses de charges. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de gestion de trésorerie. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les petites entreprises manquent de marge pour absorber les hausses de charges. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.541,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Supprimer les réunions publiques et toutes les mesures.","Attendre que les désaccords disparaissent spontanément.","Tester la solution, consulter les personnes concernées et publier un bilan.","Appliquer définitivement le projet sans recueillir d’avis."],"correct":"C","explanation":"Le compromis consiste en une expérimentation limitée, évaluée et ouverte aux retours.","transcript":"Question 23.\nVous écoutez une table ronde consacrée à économie et entreprises.\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des achats mutualisés et des conseils adaptés à chaque activité.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les petites entreprises manquent de marge pour absorber les hausses de charges.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde consacrée à économie et entreprises."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des achats mutualisés et des conseils adaptés à chaque activité."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les petites entreprises manquent de marge pour absorber les hausses de charges."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":55.274,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les personnes interrogées ont toutes répondu dans plusieurs langues.","L'enquête interroge surtout les utilisateurs présents et ignore les personnes écartées du service.","Les enquêteurs ont choisi un questionnaire trop long pour être imprimé.","Les résultats portent sur une activité qui n’existe plus."],"correct":"B","explanation":"Les personnes ayant abandonné le service ne sont pas représentées dans l’enquête.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le mentorat des commerces indépendants. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les petites entreprises manquent de marge pour absorber les hausses de charges. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le mentorat des commerces indépendants. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les petites entreprises manquent de marge pour absorber les hausses de charges. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.099,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Le besoin d'améliorer le service sans négliger les effets sur d'autres usagers.","La volonté unanime de supprimer toute activité dans la région.","L’absence complète d’obstacles techniques et sociaux.","Une décision de remplacer les responsables par des visiteurs."],"correct":"A","explanation":"Le reportage oppose l’objectif d’amélioration aux préoccupations concrètes des personnes affectées.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la chambre de commerce d'Amiens, une initiative propose des achats mutualisés et des conseils adaptés à chaque activité. Les responsables espèrent ainsi répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges.\nNous soutenons l’objectif général, mais il faut prendre en compte la prévisibilité des coûts et l'accès au financement. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que diversifier les revenus et éviter la dépendance aux subventions. Pourtant, les délais de livraison sont parfois difficiles à anticiper. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la chambre de commerce d'Amiens, une initiative propose des achats mutualisés et des conseils adaptés à chaque activité. Les responsables espèrent ainsi répondre à une difficulté bien connue : les petites entreprises manquent de marge pour absorber les hausses de charges."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la prévisibilité des coûts et l'accès au financement. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que diversifier les revenus et éviter la dépendance aux subventions. Pourtant, les délais de livraison sont parfois difficiles à anticiper. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":55.817,"slotSeconds":72},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Le service n’a jamais accueilli le moindre participant.","Toutes les étapes du projet ont été abandonnées avant le lancement.","La responsable souhaite désormais éviter de rencontrer les usagers.","Les premiers résultats sont encourageants, mais le suivi à long terme reste insuffisant."],"correct":"D","explanation":"Elle souligne la persistance de difficultés et l’absence de recul sur les résultats.","transcript":"Question 26.\nVous avez lancé un accompagnement gratuit à la transition numérique. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les délais de livraison sont parfois difficiles à anticiper. Et nous n’avons pas encore assez de recul pour mesurer la viabilité des entreprises au-delà de leur première année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé un accompagnement gratuit à la transition numérique. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les délais de livraison sont parfois difficiles à anticiper. Et nous n’avons pas encore assez de recul pour mesurer la viabilité des entreprises au-delà de leur première année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":47.666,"slotSeconds":64},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Interdire aux utilisateurs de changer leurs rendez-vous.","Réserver le dispositif aux employés travaillant tôt.","Améliorer l'accès le matin tout en maintenant une possibilité de visite en soirée.","Fermer le service chaque après-midi pour réduire les coûts."],"correct":"C","explanation":"Ils cherchent à répondre aux besoins de deux catégories d’usagers, pas à en exclure une.","transcript":"Question 27.\nPlusieurs personnes demandent que le mentorat des commerces indépendants ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le mentorat des commerces indépendants ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.294,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Avoir supprimé toutes les dépenses de matériel dès le départ.","Avoir choisi les solutions avant de comprendre les besoins des utilisateurs.","Avoir consacré trop de temps à rencontrer des usagers très différents.","Avoir demandé une évaluation du service après son ouverture."],"correct":"B","explanation":"L’experte critique une conception descendante sans consultation préalable.","transcript":"Question 28.\nLe projet de un espace de vente collectif a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la prévisibilité des coûts et l'accès au financement est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un espace de vente collectif a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la prévisibilité des coûts et l'accès au financement est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":50.568,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L'un privilégie les indicateurs chiffrés, l'autre réclame aussi des observations qualitatives.","L’un souhaite interdire toute mesure, l’autre veut supprimer les témoignages.","Les invités défendent tous deux le remplacement des résultats par des opinions.","Le débat oppose deux lieux sans rapport avec l’évaluation."],"correct":"A","explanation":"L’opposition porte sur l’importance relative des chiffres et des observations de terrain.","transcript":"Question 29.\nVous écoutez un débat consacré à économie et entreprises.\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions mesurer la viabilité des entreprises au-delà de leur première année et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les petites entreprises manquent de marge pour absorber les hausses de charges. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré à économie et entreprises."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions mesurer la viabilité des entreprises au-delà de leur première année et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les petites entreprises manquent de marge pour absorber les hausses de charges. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":49.955,"slotSeconds":67},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Interdire chaque modification, même mineure, pour toujours.","Effacer toutes les traces historiques avant de réutiliser le lieu.","Transformer nécessairement chaque site en commerce privé.","Conserver les traces significatives tout en permettant des usages adaptés aux besoins actuels."],"correct":"D","explanation":"L’invitée défend une conservation compatible avec l’évolution des usages.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de gestion de trésorerie, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de gestion de trésorerie, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.538,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Considérer que toutes les transformations se produisent à la même vitesse.","Éviter de suivre les participants une fois le projet ouvert.","Distinguer une amélioration immédiate d’un changement durable.","Mesurer seulement les résultats du premier jour."],"correct":"C","explanation":"La conférencière recommande de distinguer une amélioration immédiate d’un changement durable.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la viabilité des entreprises au-delà de leur première année. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les petites entreprises manquent de marge pour absorber les hausses de charges. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la viabilité des entreprises au-delà de leur première année. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les petites entreprises manquent de marge pour absorber les hausses de charges. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":54.259,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Mettre sur le même plan toutes les estimations, indépendamment des preuves.","Expliquer les hypothèses, les marges d'incertitude et les conditions de révision.","Présenter une prédiction unique comme absolument certaine.","Renoncer à communiquer toute information tant que les résultats ne sont pas parfaits."],"correct":"B","explanation":"Elle défend une communication transparente sur les limites et la robustesse des prévisions.","transcript":"Question 32.\nVous avancez des projections concernant le mentorat des commerces indépendants, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le mentorat des commerces indépendants, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":51.62,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Le nombre de visiteurs ou de participants ne suffit pas à mesurer les bénéfices réels.","La hausse de fréquentation prouve à elle seule le succès de toutes les mesures.","Les données chiffrées ne peuvent jamais apporter d’information utile.","L’évaluation doit porter exclusivement sur le coût du matériel."],"correct":"A","explanation":"La chroniqueuse distingue un indicateur de fréquentation et une véritable mesure des effets.","transcript":"Question 33.\nDans la chambre de commerce d'Amiens, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis un accompagnement gratuit à la transition numérique. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la viabilité des entreprises au-delà de leur première année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la chambre de commerce d'Amiens, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis un accompagnement gratuit à la transition numérique. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la viabilité des entreprises au-delà de leur première année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":47.328,"slotSeconds":65},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Supprimer tous les guichets avant d'étudier les difficultés.","Considérer que le nombre de connexions mesure à lui seul la réussite.","Limiter toute consultation aux personnes ayant conçu le dispositif.","Tester le service avec divers usagers et conserver une aide humaine accessible."],"correct":"D","explanation":"Les intervenants conviennent d’associer les usagers à l’évaluation et de maintenir une assistance.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la chambre de commerce d'Amiens.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment la question de la prévisibilité des coûts et l'accès au financement.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la chambre de commerce d'Amiens."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment la question de la prévisibilité des coûts et l'accès au financement."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.488,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Une étude de terrain peut conduire à modifier une installation.","Les utilisateurs ont parfois besoin d’explications adaptées.","Un équipement performant sur le papier garantit automatiquement un résultat sur le terrain.","Les usages réels et l’entretien influencent les résultats obtenus."],"correct":"C","explanation":"L’invitée conteste précisément l’idée que la performance technique suffise à garantir l’efficacité réelle.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la pépinière d'entreprises affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la pépinière d'entreprises affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.911,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Lorsque le seul critère retenu est le nombre de présences.","Lorsque chacun peut choisir ses activités et participer librement.","Lorsque tous les participants sont obligés d’assister à chaque réunion.","Lorsque les organisateurs imposent les mêmes rôles à toutes les générations."],"correct":"B","explanation":"L’invitée met l’accent sur le volontariat, le choix et la réciprocité.","transcript":"Question 36.\nVotre initiative autour de un atelier de gestion de trésorerie réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également veiller à la prévisibilité des coûts et l'accès au financement. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de gestion de trésorerie réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également veiller à la prévisibilité des coûts et l'accès au financement. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":52.327,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Leurs différences révèlent des points de vue qu'il faut confronter aux faits vérifiables.","Parce que toutes les affirmations contradictoires sont nécessairement exactes.","Parce qu’il faut éviter de vérifier les dates et les décisions.","Parce que la version la plus émouvante doit toujours être retenue."],"correct":"A","explanation":"Elle distingue les faits vérifiables des expériences vécues et situe les témoignages dans leur contexte.","transcript":"Question 37.\nDans votre étude concernant le mentorat des commerces indépendants, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le mentorat des commerces indépendants, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.267,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Une forte fréquentation garantit toujours la durabilité d’un projet.","La prudence exige de refuser toute expérimentation nouvelle.","Le seul enjeu est de rendre la communication plus spectaculaire.","Une initiative populaire peut fragiliser les conditions mêmes de sa réussite."],"correct":"D","explanation":"L’exposé souligne le risque de confondre popularité immédiate et progrès durable.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du domaine de économie et entreprises.  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accompagnement gratuit à la transition numérique peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les petites entreprises manquent de marge pour absorber les hausses de charges. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la prévisibilité des coûts et l'accès au financement. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du domaine de économie et entreprises.  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un accompagnement gratuit à la transition numérique peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les petites entreprises manquent de marge pour absorber les hausses de charges. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la prévisibilité des coûts et l'accès au financement. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":64.211,"slotSeconds":82},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Considérer la fréquentation initiale comme une garantie suffisante de financement.","Supprimer toute évaluation afin d’accélérer la croissance.","Prévoir des ressources durables, répartir les responsabilités et évaluer les effets réels.","Prolonger indéfiniment l’effort exceptionnel des premiers bénévoles."],"correct":"C","explanation":"L’invitée insiste sur la viabilité financière et humaine, ainsi que sur le suivi à long terme.","transcript":"Question 39.\nVotre programme, qui concerne le mentorat des commerces indépendants, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les délais de livraison sont parfois difficiles à anticiper. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la viabilité des entreprises au-delà de leur première année. L’idée n’est pas d’abandonner l’ambition de départ : diversifier les revenus et éviter la dépendance aux subventions. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre programme, qui concerne le mentorat des commerces indépendants, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les délais de livraison sont parfois difficiles à anticiper. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la viabilité des entreprises au-delà de leur première année. L’idée n’est pas d’abandonner l’ambition de départ : diversifier les revenus et éviter la dépendance aux subventions. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":65.086,"slotSeconds":83}]}$paper17$::jsonb)
on conflict(id,version) do nothing;
do $$begin
 if not exists(select 1 from academy_tcf_listening.papers
  where id='tcf-listening-17' and version='tcf-listening-2026-11-test17-v1'
    and content->>'seconds'='2100'
    and jsonb_array_length(content->'questions')=39)
 then raise exception 'Complete paper missing';end if;
 if exists(select 1 from academy_tcf_listening.published
  where test_id='tcf-listening-17' and version<>'tcf-listening-2026-11-test17-v1')
 then raise exception 'Another listening version is already active';end if;
